"""The `kizen` an eval session runs: the real CLI, with every call logged.

`write_shim` drops an executable named `kizen` into a run's `bin/`. It runs
the real CLI with the same arguments, stdin, stdout, stderr and exit code, and
appends one JSON line per call to the run's log. Measuring here, not in the
agent's transcript, means the numbers don't depend on which agent or model
drove the session.
"""

from __future__ import annotations

import stat
import sys
from pathlib import Path

_TEMPLATE = """\
#!{python}
# Generated by evals/shim.py. Runs the real kizen CLI and logs the call.
import json, os, subprocess, sys, threading, time

REAL = {real!r}
LOG = {log!r}
PROFILE = {profile!r}
TAIL = 4000


def pump(src, dst, keep):
    for chunk in iter(lambda: src.read1(65536), b""):
        dst.write(chunk)
        dst.flush()
        keep["bytes"] += len(chunk)
        keep["tail"] = (keep["tail"] + chunk)[-TAIL:]


env = dict(os.environ)
if PROFILE:
    env["KIZEN_PROFILE"] = PROFILE
started = time.time()
proc = subprocess.Popen(REAL + sys.argv[1:], env=env, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
out, err = {{"bytes": 0, "tail": b""}}, {{"bytes": 0, "tail": b""}}
threads = [
    threading.Thread(target=pump, args=(proc.stdout, sys.stdout.buffer, out)),
    threading.Thread(target=pump, args=(proc.stderr, sys.stderr.buffer, err)),
]
for t in threads:
    t.start()
code = proc.wait()
for t in threads:
    t.join()
record = {{
    "ts": round(started, 3),
    "argv": sys.argv[1:],
    "exit_code": code,
    "duration_ms": int((time.time() - started) * 1000),
    "stdout_bytes": out["bytes"],
    "stderr_bytes": err["bytes"],
    "stderr_tail": err["tail"].decode("utf-8", "replace"),
    "stdout_tail": out["tail"].decode("utf-8", "replace") if code else "",
}}
with open(LOG, "a") as fh:
    fh.write(json.dumps(record) + "\\n")
sys.exit(code)
"""


def default_real_kizen() -> list[str]:
    """The `kizen` next to the interpreter running the harness."""
    return [str(Path(sys.executable).parent / "kizen")]


def write_shim(bin_dir: Path, log: Path, real: list[str], profile: str | None) -> Path:
    bin_dir.mkdir(parents=True, exist_ok=True)
    path = bin_dir / "kizen"
    path.write_text(
        _TEMPLATE.format(
            python=sys.executable, real=real, log=str(log), profile=profile
        )
    )
    path.chmod(path.stat().st_mode | stat.S_IXUSR | stat.S_IXGRP | stat.S_IXOTH)
    return path
